[
  {
    "requirement": "The system shall display a mandatory initial notice upon launch informing users not to enter personal data, disclosing third-party data sharing terms, and providing a hyperlink to the full ICO Privacy Policy."
  },
  {
    "requirement": "The system shall not persist or store any user interaction data unless the user actively transitions from the chatbot session into the online registration flow."
  },
  {
    "requirement": "The system shall present three primary navigation options at initialization: 'Do I need to pay?', 'How much do I need to pay?', and 'Do I need to register a DPO?'."
  },
  {
    "requirement": "The system shall process user free-text inputs and map them against a repository of pre-populated storycards covering 27 frequently asked questions regarding Data Protection Fees."
  },
  {
    "requirement": "When an incoming user query cannot be matched to a pre-loaded storycard, the system shall search the public ICO website and display relevant search result links to the user."
  },
  {
    "requirement": "If the system cannot resolve a user's query through storycards or website search, it shall present a prompt directing the user to the ICO 'Contact Us' page for human assistance."
  },
  {
    "requirement": "The system shall provide conversational session controls that allow users to view previous responses, save progress, and navigate seamlessly to the online fee payment and registration portal."
  },
  {
    "requirement": "The system architecture shall enforce technical data isolation controls to ensure that third-party licensors (ICS.AI) have no direct access to ICO internal operational data."
  },
  {
    "requirement": "The system shall aggregate and report anonymized operational metrics—including query volume, resolution rates, and first-time response accuracy—to support quarterly governance and accuracy reviews."
  },
  {
    "requirement": "The system shall operate strictly as an informational and navigational guidance tool without executing automated legal or binding fee-tier assessment decisions."
  }
]

